CREATE TABLE wb_candidate_groups(id text PRIMARY KEY,project_id text NOT NULL REFERENCES wb_projects(id) ON DELETE CASCADE,chapter_id text NOT NULL REFERENCES wb_chapters(id) ON DELETE CASCADE,status text NOT NULL,input jsonb NOT NULL,run_ids jsonb NOT NULL DEFAULT '[]',review_ids jsonb NOT NULL DEFAULT '{}',rankings jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
